  const SOFT = [["중간고사에 그대로 나오니까", "다음 실습에서 그대로 쓰니까"], ["중간고사에 그대로 나온다고 했다", "다음 실습에서 그대로 쓴다고 했다"],
    ["쪽지 퀴즈 볼 거예요", "확인 문제를 같이 풀 거예요"], ["쪽지 퀴즈가 있다", "확인 문제를 함께 푼다"], ["쪽지 퀴즈", "확인 문제"], ["퀴즈", "확인 문제"]];
